import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as t,a as r,b as s}from"./chunks/M-S-SY3.DDtr6WYL.js";import{_ as o}from"./chunks/M-S-SY2.BC5ErUru.js";import{_ as n}from"./chunks/DIS.DdpTdGGD.js";import{_ as l,o as p,c,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"Configurare un follower Sync","description":"","frontmatter":{"source_hash":"2d97e8913b","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/syncsetup.md","filePath":"it/use/syncsetup.md"}'),m={name:"it/use/syncsetup.md"};function h(u,e,g,f,b,z){return p(),c("div",null,[...e[0]||(e[0]=[d('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Impostazioni xDrip+ Sync</p></div><div class="warning custom-block"><p class="custom-block-title">Vecchio xDrip Sync</p><p>A luglio 2024 Google ha chiuso la <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">Firebase API</a> deprecata che xDrip usava per xDrip Sync.<br> Aggiorna xDrip a una versione successiva al <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">23 luglio 2024</a> per usare il metodo Sync legacy.<br> Si consiglia di aggiornare xDrip almeno all&#39;ultima release.</p></div><p>xDrip offre un meccanismo esclusivo di sincronizzazione in tempo reale tra dispositivi Android, che rende la condivisione di glicemia e trattamenti il più semplice possibile.</p><br><p><a href="https://www.youtube.com/watch?v=LcgjfbYcWkE" target="_blank" rel="noreferrer">Qui il video di riferimento originale</a>.</p><h3 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>I <a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">Google Play services</a> sono indispensabili per usare questa funzione. Assicurati che siano presenti, attivati e non soggetti all&#39;ottimizzazione della batteria.</p></div><p>Il telefono master di xDrip è il dispositivo che riceve effettivamente le letture glicemiche direttamente da un sensore, un bridge o un&#39;app.<br> Rendere master di xDrip Sync un dispositivo follower serve a poco, a meno che il follower non possa usare la stessa sorgente dati.</p><p>Il master deve ricevere i dati in modo affidabile. Se il follower non ha dati, verifica sempre prima il master.</p><h2 id="setup-master" tabindex="-1">Configura il master <a class="header-anchor" href="#setup-master" aria-label="Permalink to &quot;Configura il master {#setup-master}&quot;">​</a></h2><p>Rendi master il telefono con la sorgente dati principale (attiva la casella):</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Impostazioni xDrip+ Sync</p><p>    <strong>Imposta come Telefono Principale (MASTER) per tel. secondari (FOLLOWER) <span class="symbol" style="float:right;"><img src="'+a+'" style="zoom:75%;">  </span></strong></p></div><br><h3 id="copy-the-sync-key" tabindex="-1">Copia la chiave di sincronizzazione <a class="header-anchor" href="#copy-the-sync-key" aria-label="Permalink to &quot;Copia la chiave di sincronizzazione {#copy-the-sync-key}&quot;">​</a></h3><h4 id="option-1-recommended" tabindex="-1">Opzione 1 (consigliata) <a class="header-anchor" href="#option-1-recommended" aria-label="Permalink to &quot;Opzione 1 (consigliata) {#option-1-recommended}&quot;">​</a></h4><p>Sul telefono master mostra il codice QR della chiave di sincronizzazione:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"> Mostra impostazioni dei codici QR</p><div style="background-color:gray;color:white;text-align:center;">  SOLO IMPOSTAZIONI USANDO XDRIP PLUS SECURITY KEY </div></div><p>Per il momento lascia il telefono master su questa schermata.</p><img src="'+t+'" style="zoom:75%;"><h5 id="option-1-bis-follower-phone-cannot-read-the-qr-code" tabindex="-1">Opzione 1 bis (il telefono follower non riesce a leggere il codice QR) <a class="header-anchor" href="#option-1-bis-follower-phone-cannot-read-the-qr-code" aria-label="Permalink to &quot;Opzione 1 bis (il telefono follower non riesce a leggere il codice QR) {#option-1-bis-follower-phone-cannot-read-the-qr-code}&quot;">​</a></h5><p>Fai uno screenshot del codice QR e invialo al telefono follower (MMS, WhatsApp, caricamento su Google Cloud, ...).</p><h4 id="option-2-complicated" tabindex="-1">Opzione 2 (complicata) <a class="header-anchor" href="#option-2-complicated" aria-label="Permalink to &quot;Opzione 2 (complicata) {#option-2-complicated}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Impostazioni xDrip+ Sync</p><p>    <strong>Chiave di sicurezza del Gruppo per sincronizzazione</strong></p></div><img src="'+o+'" style="zoom:75%;"><br><h2 id="setup-follower" tabindex="-1">Configura il follower <a class="header-anchor" href="#setup-follower" aria-label="Permalink to &quot;Configura il follower {#setup-follower}&quot;">​</a></h2><p>Rendi follower tutti gli altri telefoni (disattiva la casella):</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Impostazioni xDrip+ Sync</p><p>    <strong>Imposta come Telefono Principale (MASTER) per tel. secondari (FOLLOWER) <span class="symbol" style="float:right;"><img src="'+n+'" style="zoom:75%;">  </span></strong></p></div><br><p>Imposta la sorgente dati del follower:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   xDrip Sync Follower</p></div><p>Maggiori informazioni sulla sorgente dati <a href="./../install/xdripfollower.html">xDrip Sync Follower</a>.</p><br><div class="warning custom-block"><p class="custom-block-title">Usa xDrip Cloud deve essere impostato allo stesso modo su tutti i telefoni</p><p>Master e follower. O è attivo su tutti, o è disattivato su tutti.</p></div><div class="admonition xdripitem"><p class="admonition-title">Usa xDrip Cloud</p><p> Usa i nuovi server cloud xDrip+. Master e follower devono avere entrambi questa impostazione selezionata.</p></div><p>Si consiglia di attivare <a href="./sync.html#use-xdrip-cloud">Usa xDrip Cloud</a> su tutti i dispositivi, perché è il metodo più a prova di futuro.</p><h3 id="copy-the-sync-key-from-the-master" tabindex="-1">Copia la chiave di sincronizzazione dal master <a class="header-anchor" href="#copy-the-sync-key-from-the-master" aria-label="Permalink to &quot;Copia la chiave di sincronizzazione dal master {#copy-the-sync-key-from-the-master}&quot;">​</a></h3><h4 id="option-1-recommended-1" tabindex="-1">Opzione 1 (consigliata) <a class="header-anchor" href="#option-1-recommended-1" aria-label="Permalink to &quot;Opzione 1 (consigliata) {#option-1-recommended-1}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configurazione automatica<br>    Camera</p></div><p>Devi autorizzare xDrip ad accedere alla fotocamera del telefono.<br> Scansiona il codice QR mostrato sul telefono master.</p><img src="'+r+'" style="zoom:75%;"><p>Ti verrà chiesto di confermare che vuoi importare queste impostazioni (assicurati di importare impostazioni sicure).</p><div class="admonition xdripitem"><p class="admonition-title">Sei sicuro?</p><p> Importa solo le impostazioni da fonti affidabili!<br>  Conferma di volere importare le impostazioni seguenti:</p><p> impostazione1<br>  impostazione2<br>  impostazione3</p><p>No  <span style="background-color:gray;color:white;text-align:center;"> Si </span></p></div><h4 id="option-1-bis-follower-phone-cannot-read-the-qr-code-1" tabindex="-1">Opzione 1 bis (il telefono follower non riesce a leggere il codice QR) <a class="header-anchor" href="#option-1-bis-follower-phone-cannot-read-the-qr-code-1" aria-label="Permalink to &quot;Opzione 1 bis (il telefono follower non riesce a leggere il codice QR) {#option-1-bis-follower-phone-cannot-read-the-qr-code-1}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configurazione automatica<br>    File immagine</p></div><p>Seleziona l&#39;immagine che contiene il codice QR.</p><img src="'+s+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Sei sicuro?</p><p> Importa solo le impostazioni da fonti affidabili!<br>  Conferma di volere importare le impostazioni seguenti:</p><p> impostazione1<br>  impostazione2<br>  impostazione3</p><p>No  <span style="background-color:gray;color:white;text-align:center;"> Si </span></p></div><h4 id="option-2-complicated-1" tabindex="-1">Opzione 2 (complicata) <a class="header-anchor" href="#option-2-complicated-1" aria-label="Permalink to &quot;Opzione 2 (complicata) {#option-2-complicated-1}&quot;">​</a></h4><p>Modifica il campo della chiave e digita <strong>esattamente</strong> la stessa chiave del master.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Impostazioni xDrip+ Sync</p><p>    <strong>Chiave di sicurezza del Gruppo per sincronizzazione</strong></p></div><img src="'+o+'" style="zoom:75%;"><br><h2 id="follower-actions" tabindex="-1">Azioni dei follower <a class="header-anchor" href="#follower-actions" aria-label="Permalink to &quot;Azioni dei follower {#follower-actions}&quot;">​</a></h2><p>Per impostazione predefinita i follower possono inviare al master trattamenti, calibrazioni e persino l&#39;avvio o l&#39;arresto del sensore.<br> Se vuoi impedirlo, disattiva <a href="./sync.html#accept-followers-actions">Accetta le azioni dei follower</a> sul master.</p><h2 id="verify" tabindex="-1">Verifica <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verifica {#verify}&quot;">​</a></h2><p>Per verificare che il follower riceva i dati, controlla lo <a href="./../troubleshoot/systemstatus.html#xdrip-sync-follower">Stato del sistema</a> sul telefono follower.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',59)])])}const k=l(m,[["render",h]]);export{S as __pageData,k as default};
